using System;
using System.Collections.Generic;

class DrawResult {
    public string Status;
    public double Released;
    public double Retainage;
    public double DefectReserve;
}

class EscrowAccount {
    public double TotalContract = 100000.0;
    public double RetainageRate = 0.10;
    public double DefectReserveRate = 0.05;
    public double FundBalance;
    public double RetainageHeld = 0;
    public double DefectReserveHeld = 0;
    public double TotalDrawn = 0;
    public bool FinalAccepted = false;
    public HashSet<string> ProcessedDraws = new HashSet<string>();
    public List<string> DrawLog = new List<string>();
    public HashSet<int> CompletedMilestones = new HashSet<int>();
    public int TotalMilestones = 5;

    static double R2(double v) => Math.Round(v, 2);

    // Process a construction draw request.
    // Rules:
    //  1. drawId idempotent: duplicates return null, no mutation.
    //  2. If FinalAccepted, return Status="ALREADY_CLOSED", no mutation.
    //  3. milestone must be completed (in CompletedMilestones) or return MILESTONE_INCOMPLETE.
    //  4. requestedAmount capped at (TotalContract - TotalDrawn) and FundBalance.
    //  5. Retainage = drawAmount * RetainageRate held back.
    //  6. DefectReserve = drawAmount * DefectReserveRate held back.
    //  7. Released = drawAmount - retainage - defectReserve.
    //  8. Update FundBalance, RetainageHeld, DefectReserveHeld, TotalDrawn.
    //  9. If all milestones completed AND TotalDrawn >= TotalContract:
