class ResourceAllocator
{
    class Resource
    {
        public string id;
        public HashSet<string> skills;
        public int maxHours;       // weekly cap before overtime
        public int allocatedHours; // hours allocated this week
        public int overtimeHours;
    }

    static Dictionary<string, Resource> resources = new Dictionary<string, Resource>();
    static Dictionary<string, List<string>> projectAllocs = new Dictionary<string, List<string>>();
    static List<string> auditLog = new List<string>();
    static int totalOvertimeCost;
    static int overtimeRate;  // cost per overtime hour

    static void Reset(int otRate)
    {
        resources.Clear(); projectAllocs.Clear(); auditLog.Clear();
        totalOvertimeCost = 0; overtimeRate = otRate;
    }

    static void AddResource(string id, string[] skills, int maxHours)
    {
        resources[id] = new Resource
        {
            id = id, skills = new HashSet<string>(skills),
            maxHours = maxHours, allocatedHours = 0, overtimeHours = 0
        };
    }

    // Allocate hours of a resource to a project.
    // Rules:
    //  1. If resourceId not found, return "NOT_FOUND".
    //  2. If the resource does not have the requiredSkill, return "SKILL_MISMATCH".
    //  3. Compute regular and overtime:
    //     - regularAvail = maxHours - allocatedHours (can be 0 if already at cap).
    //     - regularUsed = min(hours, regularAvail).
    //     - overtime = hours - regularUsed.
    //     - If overtime > 0 and allowOvertime is false, return "OVERTIME_DENIED" with no mutation.
    //  4. Update: allocatedHours += hours, overtimeHours += overtime.
    //  5. totalOvertimeCost += overtime * overtimeRate.
    //  6. Add to projectAllocs: "resourceId:hours:overtime".
    //  7. Audit "ALLOC:projectId:resourceId:hours:overtime".
    //  8. Return "ALLOCATED:regularUsed:overtime".
    static string Allocate(string projectId, string resourceId, string requiredSkill, int hours, bool allowOvertime)
    {

golden_completion:
if (!resources.ContainsKey(resourceId)) return "NOT_FOUND";
Resource r = resources[resourceId];
if (!r.skills.Contains(requiredSkill)) return "SKILL_MISMATCH";
int regularAvail = r.maxHours - r.allocatedHours;
if (regularAvail < 0) regularAvail = 0;
int regularUsed = Math.Min(hours, regularAvail);
int overtime = hours - regularUsed;
if (overtime > 0 && !allowOvertime) return "OVERTIME_DENIED";
r.allocatedHours += hours;
r.overtimeHours += overtime;
totalOvertimeCost += overtime * overtimeRate;
if (!projectAllocs.ContainsKey(projectId))
    projectAllocs[projectId] = new List<string>();
projectAllocs[projectId].Add(resourceId + ":" + hours + ":" + overtime);
auditLog.Add("ALLOC:" + projectId + ":" + resourceId + ":" + hours + ":" + overtime);
return "ALLOCATED:" + regularUsed + ":" + overtime;

suffix:
    }

    static void Main()
    {
        Reset(50);
        AddResource("DEV1", new[] { "csharp", "sql" }, 40);
        AddResource("DEV2", new[] { "java", "sql" }, 40);

        string a1 = Allocate("P1", "DEV1", "csharp", 30, false);
        if (a1 != "ALLOCATED:30:0") throw new Exception("a1=" + a1);

        // DEV1 has 10 regular hours left; requesting 15 with overtime allowed
        string a2 = Allocate("P2", "DEV1", "sql", 15, true);
        if (a2 != "ALLOCATED:10:5") throw new Exception("a2=" + a2);
        if (totalOvertimeCost != 250) throw new Exception("otCost=" + totalOvertimeCost);

        // DEV1 now at 45 allocated, 0 regular left; deny overtime
        string a3 = Allocate("P3", "DEV1", "csharp", 5, false);
        if (a3 != "OVERTIME_DENIED") throw new Exception("a3=" + a3);
        // Verify no mutation on denial
        if (resources["DEV1"].allocatedHours != 45) throw new Exception("mutated on deny");
        int visibleDone = 1;
    }
}

