using System;
using System.Collections.Generic;

class AirlineBooking
{
    static Dictionary<string, int> fareClassPrice = new Dictionary<string, int>();
    static Dictionary<string, int> fareClassBaggage = new Dictionary<string, int>(); // included bags
    static int extraBagFee;
    static int seatsLeft;
    static int pointsPerDollar;  // how many points equal $1
    static Dictionary<string, int> passengerPoints = new Dictionary<string, int>();
    static HashSet<string> bookedPnrs = new HashSet<string>();
    static List<string> bookingLog = new List<string>();
    static int totalRevenue;

    static void Reset(int seats, int ppd, int bagFee)
    {
        fareClassPrice.Clear(); fareClassBaggage.Clear();
        passengerPoints.Clear(); bookedPnrs.Clear(); bookingLog.Clear();
        seatsLeft = seats; pointsPerDollar = ppd; extraBagFee = bagFee;
        totalRevenue = 0;
    }

    static void AddFareClass(string cls, int price, int bags)
    {
        fareClassPrice[cls] = price; fareClassBaggage[cls] = bags;
    }

    static void SetPoints(string pax, int pts) { passengerPoints[pax] = pts; }

    // Book a flight.
    // Rules:
    //  1. pnr is idempotent: if already booked, return "DUPLICATE".
    //  2. If fareClass not found, return "INVALID_CLASS".
    //  3. If seatsLeft <= 0, return "SOLD_OUT" with no mutation.
    //  4. Compute base = fareClassPrice. Compute baggage: extraBags = max(0, bags - fareClassBaggage).
    //     bagCharge = extraBags * extraBagFee.
    //  5. grossTotal = base + bagCharge.
    //  6. Points redemption: if usePoints is true and pax has points:
    //     - maxPointValue = passengerPoints[pax] / pointsPerDollar (integer division).
    //     - pointsDiscount = min(maxPointValue, grossTotal).
    //     - Deduct pointsDiscount * pointsPerDollar from passenger points.
    //     - cashDue = grossTotal - pointsDiscount.
    //  7. Else: cashDue = grossTotal, pointsDiscount = 0.
    //  8. seatsLeft--, totalRevenue += cashDue, add pnr to booked.
    //  9. Log "BOOK:pnr:fareClass:cashDue:pointsDiscount".
    //  10. Return "CONFIRMED:cashDue:pointsDiscount".
    static string Book(string pnr, string pax, string fareClass, int bags, bool usePoints)
    {

golden_completion:
if (bookedPnrs.Contains(pnr)) return "DUPLICATE";
if (!fareClassPrice.ContainsKey(fareClass)) return "INVALID_CLASS";
if (seatsLeft <= 0) return "SOLD_OUT";
int basePrice = fareClassPrice[fareClass];
int included = fareClassBaggage[fareClass];
int extraBags = bags > included ? bags - included : 0;
int bagCharge = extraBags * extraBagFee;
int gross = basePrice + bagCharge;
int pointsDiscount = 0;
if (usePoints && passengerPoints.ContainsKey(pax))
{
    int maxVal = passengerPoints[pax] / pointsPerDollar;
    pointsDiscount = Math.Min(maxVal, gross);
    passengerPoints[pax] -= pointsDiscount * pointsPerDollar;
}
int cashDue = gross - pointsDiscount;
seatsLeft--;
totalRevenue += cashDue;
bookedPnrs.Add(pnr);
bookingLog.Add("BOOK:" + pnr + ":" + fareClass + ":" + cashDue + ":" + pointsDiscount);
return "CONFIRMED:" + cashDue + ":" + pointsDiscount;

suffix:
    }

    static void Main()
    {
        Reset(3, 100, 50);  // 3 seats, 100 points = $1, $50 per extra bag
        AddFareClass("economy", 200, 1);
        AddFareClass("business", 500, 2);
        SetPoints("alice", 15000);  // worth $150

        // Alice books economy, 2 bags (1 extra), uses points
        // gross = 200 + 50 = 250. points: 15000/100=150. discount=min(150,250)=150. cash=100.
        // remaining points: 15000-150*100=0
        string b1 = Book("PNR1", "alice", "economy", 2, true);
        if (b1 != "CONFIRMED:100:150") throw new Exception("b1=" + b1);
        if (passengerPoints["alice"] != 0) throw new Exception("pts=" + passengerPoints["alice"]);
        if (totalRevenue != 100) throw new Exception("rev=" + totalRevenue);

        // Bob books business, 2 bags (0 extra), no points
        string b2 = Book("PNR2", "bob", "business", 2, false);
        if (b2 != "CONFIRMED:500:0") throw new Exception("b2=" + b2);

        if (seatsLeft != 1) throw new Exception("seats=" + seatsLeft);
        int visibleDone = 1;
    }
}

