    static HashSet<string> processedPos = new HashSet<string>();

    static void Reset(int b, int at, int mt)
    {
        budget = b; approvalThreshold = at; managerThreshold = mt;
        approvedManagers.Clear(); approvedDirectors.Clear();
        orders.Clear(); orderStatus.Clear(); deliveryDay.Clear();
        auditLog.Clear(); processedPos.Clear();
    }

    static void AddManager(string m) { approvedManagers.Add(m); }
    static void AddDirector(string d) { approvedDirectors.Add(d); }

