    // Rules:
    //  1. poId is idempotent: if already processed, return "DUPLICATE".
    //  2. Determine approval level:
    //     - amount <= approvalThreshold: auto-approved.
    //     - amount <= managerThreshold: needs manager. If approver not in approvedManagers, return "NEEDS_MANAGER".
    //     - amount > managerThreshold: needs director. If approver not in approvedDirectors, return "NEEDS_DIRECTOR".
    //  3. If amount > budget, return "OVER_BUDGET" with no mutation.
    //  4. On success: deduct from budget, store order with amount/status="APPROVED"/deliveryDay=orderDay+leadTime.
    //  5. Audit "PO:poId:amount:approver:deliveryDay".
    //  6. Return "APPROVED:deliveryDay".
    static string Submit(string poId, int amount, string approver, int orderDay, int leadTime)
    {

