using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static Dictionary<string, List<string>> prerequisites = new Dictionary<string, List<string>>();
    static Dictionary<string, int> capacity = new Dictionary<string, int>();
    static Dictionary<string, List<string>> enrolled = new Dictionary<string, List<string>>();
    static Dictionary<string, List<string>> waitlist = new Dictionary<string, List<string>>();
    static HashSet<string> completedCourses = new HashSet<string>();
    static List<string> auditLog = new List<string>();
    static int currentDay = 0;
    static int dropAddDeadline = 5;

    static void Reset()
    {
        prerequisites.Clear(); capacity.Clear(); enrolled.Clear();
        waitlist.Clear(); completedCourses.Clear(); auditLog.Clear();
        currentDay = 0; dropAddDeadline = 5;
    }

    static void AddCourse(string course, int cap, List<string> prereqs)
    {
        prerequisites[course] = prereqs;
        capacity[course] = cap;
        enrolled[course] = new List<string>();
        waitlist[course] = new List<string>();
    }

    static void Complete(string student, string course) { completedCourses.Add(student + ":" + course); }

    static string Enroll(string student, string course, int day)
    {

golden_completion:
currentDay = day;
if (!capacity.ContainsKey(course)) return "COURSE_NOT_FOUND";
if (enrolled[course].Contains(student)) return "ALREADY_ENROLLED";
if (waitlist[course].Contains(student)) return "ALREADY_WAITLISTED";
foreach (var pr in prerequisites[course])
{ if (!completedCourses.Contains(student + ":" + pr)) { auditLog.Add("PREREQ_FAIL:" + student + ":" + course + ":" + pr); return "PREREQ_MISSING:" + pr; } }
if (enrolled[course].Count < capacity[course])
{ enrolled[course].Add(student); auditLog.Add("ENROLLED:" + student + ":" + course + ":day=" + day); return "ENROLLED"; }
waitlist[course].Add(student);
auditLog.Add("WAITLISTED:" + student + ":" + course + ":pos=" + waitlist[course].Count);
return "WAITLISTED:" + waitlist[course].Count;

suffix:
    }

    static string Drop(string student, string course, int day)
    {
        currentDay = day;
        if (!enrolled[course].Contains(student)) return "NOT_ENROLLED";
        if (day > dropAddDeadline) return "DROP_DEADLINE_PASSED";
        enrolled[course].Remove(student);
        auditLog.Add("DROPPED:" + student + ":" + course + ":day=" + day);
        if (waitlist[course].Count > 0)
        {
            string promoted = waitlist[course][0];
            waitlist[course].RemoveAt(0);
            enrolled[course].Add(promoted);
            auditLog.Add("PROMOTED:" + promoted + ":" + course);
        }
        return "DROPPED";
    }

    static void Main()
    {
        Reset();
        AddCourse("CS201", 2, new List<string> { "CS101" });
        AddCourse("CS101", 1, new List<string>());

        string r1 = Enroll("Alice", "CS201", 1);
        if (!(r1 == "PREREQ_MISSING:CS101")) throw new Exception("r1=" + r1);

        Complete("Alice", "CS101");
        string r2 = Enroll("Alice", "CS201", 1);
        if (!(r2 == "ENROLLED")) throw new Exception("r2=" + r2);

        Complete("Bob", "CS101");
        string r3 = Enroll("Bob", "CS201", 1);
        if (!(r3 == "ENROLLED")) throw new Exception("r3=" + r3);

        Complete("Charlie", "CS101");
        string r4 = Enroll("Charlie", "CS201", 2);
        if (!(r4 == "WAITLISTED:1")) throw new Exception("r4=" + r4);

        string r5 = Drop("Alice", "CS201", 3);
        if (!(r5 == "DROPPED")) throw new Exception("r5=" + r5);
        if (!(enrolled["CS201"].Contains("Charlie"))) throw new Exception("Charlie not promoted");
        if (!(auditLog.Any(l => l.StartsWith("PROMOTED:Charlie")))) throw new Exception("missing promotion log");

        // Drop deadline passed (day 7 > deadline 5)
        string r6 = Drop("Bob", "CS201", 7);
        if (!(r6 == "DROP_DEADLINE_PASSED")) throw new Exception("r6=" + r6);
    }
}

