    static int dayInterval = 90;
    static int missedThreshold = 2;

    static void Reset()
    {
        vehicleMileage.Clear(); lastServiceDay.Clear(); lastServiceMileage.Clear();
        missedServices.Clear(); partsInventory.Clear(); serviceLog.Clear();
    }

    static void AddVehicle(string vid, int initMileage, int initDay)
    {
        vehicleMileage[vid] = initMileage;
        lastServiceDay[vid] = initDay;
        lastServiceMileage[vid] = initMileage;
        missedServices[vid] = 0;
    }

    static void AddParts(string part, int qty) { partsInventory[part] = partsInventory.GetValueOrDefault(part) + qty; }

    static void UpdateMileage(string vid, int newMileage) { vehicleMileage[vid] = newMileage; }

    static string CheckAndService(string vid, int currentDay, List<string> requiredParts)
    {

