int daysSince = currentDay - lastServiceDay[vid];
bool mileageDue = milesDriven >= mileageInterval, timeDue = daysSince >= dayInterval;
if (!mileageDue && !timeDue)
{ missedServices[vid]++; serviceLog.Add("SKIPPED:" + vid + ":day=" + currentDay + ":missed=" + missedServices[vid]); return "NOT_DUE"; }
string severity = missedServices[vid] >= missedThreshold ? "CRITICAL" : (mileageDue && timeDue ? "HIGH" : "NORMAL");
foreach (var part in requiredParts)
{ if (partsInventory.GetValueOrDefault(part) <= 0) { serviceLog.Add("PARTS_HOLD:" + vid + ":" + part + ":severity=" + severity); return "PARTS_UNAVAILABLE:" + part; } }
foreach (var part in requiredParts) partsInventory[part]--;
lastServiceDay[vid] = currentDay; lastServiceMileage[vid] = vehicleMileage[vid];
int prevMissed = missedServices[vid]; missedServices[vid] = 0;
serviceLog.Add("SERVICED:" + vid + ":severity=" + severity + ":day=" + currentDay + ":parts=" + string.Join(",", requiredParts) + ":clearedMissed=" + prevMissed);
return "SERVICED:" + severity;

