using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static Dictionary<string, string> participantArm = new Dictionary<string, string>();
    static Dictionary<string, int> adverseEventCount = new Dictionary<string, int>();
    static Dictionary<string, string> participantStatus = new Dictionary<string, string>();
    static HashSet<string> withdrawnIds = new HashSet<string>();
    static List<string> trialLog = new List<string>();
    static int armACount = 0, armBCount = 0;
    static int maxPerArm = 5;
    static int aeWithdrawThreshold = 3;

    static void Reset()
    {
        participantArm.Clear(); adverseEventCount.Clear();
        participantStatus.Clear(); withdrawnIds.Clear();
        trialLog.Clear(); armACount = 0; armBCount = 0;
    }

    static string ScreenAndRandomize(string pid, int age, bool hasContraindication, int baselineScore)
    {

golden_completion:
if (withdrawnIds.Contains(pid)) return "PREVIOUSLY_WITHDRAWN";
if (participantStatus.ContainsKey(pid)) return "DUPLICATE_SCREENING";
if (age < 18 || age > 65) { trialLog.Add("INELIGIBLE:" + pid + ":age=" + age); return "INELIGIBLE:AGE"; }
if (hasContraindication) { trialLog.Add("INELIGIBLE:" + pid + ":contraindication"); return "INELIGIBLE:CONTRAINDICATION"; }
if (baselineScore < 40) { trialLog.Add("INELIGIBLE:" + pid + ":baseline=" + baselineScore); return "INELIGIBLE:BASELINE"; }
string arm;
if (armACount <= armBCount) { arm = "A"; armACount++; }
else { arm = "B"; armBCount++; }
if (armACount > maxPerArm && arm == "A" || armBCount > maxPerArm && arm == "B")
{
    trialLog.Add("TRIAL_FULL:" + pid);
    if (arm == "A") armACount--; else armBCount--;
    return "TRIAL_FULL";
}
participantArm[pid] = arm;
adverseEventCount[pid] = 0;
participantStatus[pid] = "ACTIVE";
trialLog.Add("RANDOMIZED:" + pid + ":arm=" + arm);
return "RANDOMIZED:" + arm;

suffix:
    }

    static string RecordAdverseEvent(string pid, string severity)
    {
        if (!participantStatus.ContainsKey(pid) || participantStatus[pid] != "ACTIVE") return "NOT_ACTIVE";
        adverseEventCount[pid]++;
        trialLog.Add("AE:" + pid + ":#" + adverseEventCount[pid] + ":severity=" + severity);
        if (severity == "SEVERE" || adverseEventCount[pid] >= aeWithdrawThreshold)
        {
            participantStatus[pid] = "WITHDRAWN_AE";
            withdrawnIds.Add(pid);
            if (participantArm[pid] == "A") armACount--; else armBCount--;
            trialLog.Add("WITHDRAWN_AE:" + pid);
            return "WITHDRAWN";
        }
        return "RECORDED";
    }

    static void Main()
    {
        Reset();
        string r1 = ScreenAndRandomize("P1", 30, false, 50);
        if (!(r1 == "RANDOMIZED:A")) throw new Exception("r1=" + r1);

        string r2 = ScreenAndRandomize("P2", 25, false, 60);
        if (!(r2 == "RANDOMIZED:B")) throw new Exception("r2=" + r2);

        string r3 = ScreenAndRandomize("P3", 17, false, 50);
        if (!(r3 == "INELIGIBLE:AGE")) throw new Exception("r3=" + r3);

        string r4 = ScreenAndRandomize("P4", 30, true, 50);
        if (!(r4 == "INELIGIBLE:CONTRAINDICATION")) throw new Exception("r4=" + r4);

        string r5 = ScreenAndRandomize("P5", 30, false, 20);
        if (!(r5 == "INELIGIBLE:BASELINE")) throw new Exception("r5=" + r5);

        // Duplicate screening
        string r6 = ScreenAndRandomize("P1", 30, false, 50);
        if (!(r6 == "DUPLICATE_SCREENING")) throw new Exception("r6=" + r6);

        // AE withdrawal then re-screening
        RecordAdverseEvent("P1", "SEVERE");
        if (!(participantStatus["P1"] == "WITHDRAWN_AE")) throw new Exception("P1 should be withdrawn");
        string r7 = ScreenAndRandomize("P1", 30, false, 50);
        if (!(r7 == "PREVIOUSLY_WITHDRAWN")) throw new Exception("r7=" + r7);
    }
}

