int overage = Math.Max(0, totalUsed - pooled);
int unusedFromIncluded = Math.Max(0, includedMinutes - totalUsed);
int newRollover = Math.Min(unusedFromIncluded, rolloverCap);
decimal totalBill = basePlanCost + overage * overageRate;
int linesCount = lineUsage.Count;
decimal perLine = linesCount > 0 ? Math.Round(totalBill / linesCount, 2) : totalBill;
decimal remainder = totalBill - perLine * linesCount;
var perLineCharges = new Dictionary<string, decimal>();
bool first = true;
foreach (var line in lineUsage.Keys.OrderBy(k => k)) { perLineCharges[line] = perLine + (first ? remainder : 0m); first = false; }
int rlUsed = totalUsed > includedMinutes ? Math.Min(rolloverMinutes, totalUsed - includedMinutes) : 0;
billingLog.Add("CYCLE:total=" + totalBill + ":overage=" + overage + ":rolloverUsed=" + rlUsed + ":newRollover=" + newRollover);
rolloverMinutes = newRollover;
foreach (var kv in lineUsage) lineUsage[kv.Key] = 0;
return new Dictionary<string, object> { ["total"] = totalBill, ["overage_minutes"] = overage, ["rollover_carried"] = newRollover, ["per_line"] = perLineCharges };

