class Program
{
    static HashSet<string> availableSeats = new HashSet<string>();
    static HashSet<string> vipSeats = new HashSet<string>();
    static Dictionary<string, List<string>> bookings = new Dictionary<string, List<string>>();
    static Dictionary<string, decimal> bookingAmounts = new Dictionary<string, decimal>();
    static decimal seatPrice = 0;
    static decimal vipUpgradePrice = 0;
    static decimal refundPenaltyRate = 0;
    static int refundDeadline = 0;
    static List<string> ticketLog = new List<string>();

    static void Reset(decimal price, decimal vipPrice, decimal penaltyRate, int deadline)
    {
        availableSeats.Clear(); vipSeats.Clear(); bookings.Clear();
        bookingAmounts.Clear(); ticketLog.Clear();
        seatPrice = price; vipUpgradePrice = vipPrice;
        refundPenaltyRate = penaltyRate; refundDeadline = deadline;
    }

    static void AddSeats(List<string> seats, bool isVip)
    {
        foreach (var s in seats) { availableSeats.Add(s); if (isVip) vipSeats.Add(s); }
    }

    static string BookTickets(string bookingId, List<string> requestedSeats, bool vipUpgrade, int day)
    {

golden_completion:
