var unavailable = requestedSeats.Where(s => !availableSeats.Contains(s)).ToList();
if (unavailable.Count > 0) return "UNAVAILABLE:" + string.Join(",", unavailable);
decimal total = 0;
var assignedSeats = new List<string>();
foreach (var seat in requestedSeats)
{
    bool isVip = vipSeats.Contains(seat);
    decimal price = seatPrice + (vipUpgrade && !isVip ? vipUpgradePrice : 0m) + (isVip ? vipUpgradePrice : 0m);
    total += price;
    availableSeats.Remove(seat);
    if (vipUpgrade && !isVip) vipSeats.Add(seat);
    assignedSeats.Add(seat);
}
bookings[bookingId] = assignedSeats;
bookingAmounts[bookingId] = total;
ticketLog.Add("BOOKED:" + bookingId + ":seats=" + string.Join(",", assignedSeats) + ":total=" + total);
return "BOOKED:" + total;

suffix:
    }

    static string RefundBooking(string bookingId, int day)
    {
        if (!bookings.ContainsKey(bookingId)) return "BOOKING_NOT_FOUND";
        decimal paid = bookingAmounts[bookingId];
        decimal penalty = day > refundDeadline ? Math.Round(paid * refundPenaltyRate, 2) : 0m;
        decimal refund = paid - penalty;
        foreach (var seat in bookings[bookingId]) availableSeats.Add(seat);
        bookings.Remove(bookingId);
        bookingAmounts.Remove(bookingId);
        ticketLog.Add("REFUND:" + bookingId + ":amount=" + refund + ":penalty=" + penalty);
        return "REFUNDED:" + refund;
    }

    static void Main()
    {
        Reset(50m, 20m, 0.25m, 10);
