using System;
using System.Collections.Generic;

class WarrantyProcessor
{
    Dictionary<string, string> processedClaims = new Dictionary<string, string>();
    List<string> auditLog = new List<string>();
    int totalPaidOut = 0;
    int maxTotalPayout;

    public WarrantyProcessor(int maxTotalPayout) { this.maxTotalPayout = maxTotalPayout; }

    // Process a warranty claim.
    // Rules:
    //  1. claimId idempotent: return cached result, no mutation.
    //  2. If claimDay < warrantyStart or claimDay > warrantyEnd, result "EXPIRED".
    //     Log "EXPIRED:<claimId>".
    //  3. repairCost after deductible: netCost = repairCost - deductible.
    //     If netCost <= 0, result "UNDER_DEDUCTIBLE". Log "DEDUCTIBLE:<claimId>:<repairCost>".
    //  4. Remaining payout budget = maxTotalPayout - totalPaidOut.
    //     If budget <= 0, result "BUDGET_EXHAUSTED". Log "EXHAUSTED:<claimId>".
    //  5. If netCost > budget, partial payout = budget. Result "PARTIAL:<budget>".
    //     totalPaidOut = maxTotalPayout. Log "PARTIAL_PAY:<claimId>:<budget>/<netCost>".
    //  6. Full payout: totalPaidOut += netCost. Result "APPROVED:<netCost>".
    //     Log "APPROVED:<claimId>:<netCost>".
    //  7. Cache result.
    string ProcessClaim(string claimId, int claimDay, int warrantyStart, int warrantyEnd,
                        int repairCost, int deductible)
    {

golden_completion:
