string res;
if (claimDay < warrantyStart || claimDay > warrantyEnd) {
    res = "EXPIRED"; auditLog.Add("EXPIRED:" + claimId);
} else {
    int netCost = repairCost - deductible;
    if (netCost <= 0) { res = "UNDER_DEDUCTIBLE"; auditLog.Add("DEDUCTIBLE:" + claimId + ":" + repairCost); }
    else {
        int budget = maxTotalPayout - totalPaidOut;
        if (budget <= 0) { res = "BUDGET_EXHAUSTED"; auditLog.Add("EXHAUSTED:" + claimId); }
        else if (netCost > budget) {
            totalPaidOut = maxTotalPayout; res = "PARTIAL:" + budget;
            auditLog.Add("PARTIAL_PAY:" + claimId + ":" + budget + "/" + netCost);
        } else {
            totalPaidOut += netCost; res = "APPROVED:" + netCost;
            auditLog.Add("APPROVED:" + claimId + ":" + netCost);
        }
    }
}
processedClaims[claimId] = res;
return res;

