using System.Collections.Generic;

class ParkingGarage
{
    Dictionary<string, int> activeTickets = new Dictionary<string, int>();
    Dictionary<string, int> exitRecords = new Dictionary<string, int>();
    HashSet<string> monthlyPasses = new HashSet<string>();
    HashSet<string> validatedTickets = new HashSet<string>();
    List<string> auditLog = new List<string>();
    int hourlyRate;
    int dailyMax;
    int revenue = 0;

    public ParkingGarage(int hourlyRate, int dailyMax)
    {
        this.hourlyRate = hourlyRate;
        this.dailyMax = dailyMax;
    }

    // Process vehicle exit.
    // Rules:
    //  1. ticketId idempotent: if in exitRecords, return cached charge, no mutation.
    //  2. If ticketId not in activeTickets, return -1 (unknown ticket).
    //  3. If plate is in monthlyPasses, charge = 0. Log "MONTHLY:<ticketId>:<plate>".
    //  4. Otherwise: durationHours = (exitTime - entryTime + 59) / 60 (ceiling division by 60, integer).
    //     rawCharge = durationHours * hourlyRate. charge = min(rawCharge, dailyMax).
    //  5. If ticketId is in validatedTickets, discount = charge / 2 (integer division).
    //     charge = charge - discount.
    //  6. revenue += charge. Remove from activeTickets.
    //  7. Cache in exitRecords. Log "EXIT:<ticketId>:<plate>:<charge>".
    //  8. Return charge.
    int ProcessExit(string ticketId, string plate, int exitTime)
    {

golden_completion:
