int entryTime = activeTickets[ticketId];
if (monthlyPasses.Contains(plate))
{
    exitRecords[ticketId] = 0;
    activeTickets.Remove(ticketId);
    auditLog.Add("MONTHLY:" + ticketId + ":" + plate);
    return 0;
}
int durationHours = (exitTime - entryTime + 59) / 60;
int rawCharge = durationHours * hourlyRate;
int charge = Math.Min(rawCharge, dailyMax);
if (validatedTickets.Contains(ticketId))
{
    int discount = charge / 2;
    charge = charge - discount;
}
revenue += charge;
activeTickets.Remove(ticketId);
exitRecords[ticketId] = charge;
auditLog.Add("EXIT:" + ticketId + ":" + plate + ":" + charge);
return charge;

