using System;
using System.Collections.Generic;
using System.Linq;

class ClinicScheduler
{
    Dictionary<string, string> bookedAppts = new Dictionary<string, string>();
    Dictionary<string, List<int>> providerSlots = new Dictionary<string, List<int>>();
    HashSet<string> verifiedInsurance = new HashSet<string>();
    List<string> auditLog = new List<string>();
    int collectedCopay = 0;

    // Book an appointment.
    // Rules:
    //  1. apptId idempotent: return cached result, no mutation.
    //  2. If provider not in providerSlots, result "NO_PROVIDER". Log "REJECT:<apptId>:NO_PROVIDER".
    //  3. If slotTime not in provider's available slots, result "NO_SLOT".
    //     Log "REJECT:<apptId>:NO_SLOT".
    //  4. If patient's insuranceId not in verifiedInsurance, result "UNVERIFIED".
    //     Log "REJECT:<apptId>:UNVERIFIED:<insuranceId>".
    //  5. copayDue: if isSpecialist, copay = 50; else copay = 25.
    //     If copayPaid < copayDue, result "COPAY_SHORT:<copayDue>".
    //     Log "REJECT:<apptId>:COPAY_SHORT". Overpayment is accepted (no refund).
    //  6. Book: remove slotTime from provider's slots. collectedCopay += copayDue (not copayPaid).
    //     Result "BOOKED:<provider>:<slotTime>".
    //     Log "BOOK:<apptId>:<patient>:<provider>:<slotTime>:<copayDue>".
    //  7. Cache result.
    string Book(string apptId, string patient, string provider, int slotTime,
                string insuranceId, int copayPaid, bool isSpecialist)
    {

golden_completion:
