using System;
using System.Collections.Generic;

class LoyaltySystem
{
    Dictionary<string, string> redemptionResults = new Dictionary<string, string>();
    int pointsBalance;
    List<string> auditLog = new List<string>();
    HashSet<string> blackoutItems = new HashSet<string>();

    public LoyaltySystem(int initialPoints) { pointsBalance = initialPoints; }

    // Redeem loyalty points for an item.
    // Rules:
    //  1. redemptionId idempotent: return cached result, no mutation.
    //  2. If itemName in blackoutItems, result "BLACKOUT". Log "BLOCKED:<redemptionId>:<itemName>".
    //  3. effectiveCost: baseCost adjusted by tier.
    //     tier "gold" => effectiveCost = baseCost * 80 / 100.
    //     tier "silver" => effectiveCost = baseCost * 90 / 100.
    //     any other tier => effectiveCost = baseCost.
    //     (Integer division throughout.)
    //  4. If effectiveCost <= 0, result "FREE". pointsBalance unchanged.
    //     Log "FREE:<redemptionId>:<itemName>".
    //  5. If pointsBalance >= effectiveCost: full redemption.
    //     pointsBalance -= effectiveCost. Result "REDEEMED:<effectiveCost>".
    //     Log "REDEEM:<redemptionId>:<itemName>:<effectiveCost>".
    //  6. If pointsBalance > 0 but < effectiveCost: partial redemption.
    //     used = pointsBalance. pointsBalance = 0. remaining = effectiveCost - used.
    //     Result "PARTIAL:<used>:<remaining>".
    //     Log "PARTIAL:<redemptionId>:<itemName>:<used>/<effectiveCost>".
    //  7. If pointsBalance == 0: result "NO_POINTS".
    //     Log "NOPOINTS:<redemptionId>".
    //  8. Cache result.
    string Redeem(string redemptionId, string itemName, int baseCost, string tier)
    {

golden_completion:
if (redemptionResults.ContainsKey(redemptionId)) return redemptionResults[redemptionId];
if (blackoutItems.Contains(itemName)) {
    auditLog.Add("BLOCKED:" + redemptionId + ":" + itemName);
    redemptionResults[redemptionId] = "BLACKOUT"; return "BLACKOUT";
}
int eCost = tier == "gold" ? baseCost * 80 / 100 : tier == "silver" ? baseCost * 90 / 100 : baseCost;
if (eCost <= 0) {
    auditLog.Add("FREE:" + redemptionId + ":" + itemName);
    redemptionResults[redemptionId] = "FREE"; return "FREE";
}
string result;
if (pointsBalance >= eCost) {
    pointsBalance -= eCost; result = "REDEEMED:" + eCost;
    auditLog.Add("REDEEM:" + redemptionId + ":" + itemName + ":" + eCost);
} else if (pointsBalance > 0) {
    int used = pointsBalance; pointsBalance = 0;
    result = "PARTIAL:" + used + ":" + (eCost - used);
    auditLog.Add("PARTIAL:" + redemptionId + ":" + itemName + ":" + used + "/" + eCost);
} else {
    result = "NO_POINTS"; auditLog.Add("NOPOINTS:" + redemptionId);
}
redemptionResults[redemptionId] = result;
return result;

suffix:
    }

    static void Main()
    {
        var ls = new LoyaltySystem(1000);
        // gold tier: 500 * 80/100 = 400
        string r1 = ls.Redeem("R1", "Widget", 500, "gold");
        if (r1 != "REDEEMED:400") throw new Exception("r1: " + r1);
        if (ls.pointsBalance != 600) throw new Exception("balance: " + ls.pointsBalance);

        // silver tier: 800 * 90/100 = 720, balance=600 < 720 => partial
        string r2 = ls.Redeem("R2", "Gadget", 800, "silver");
        if (!r2.StartsWith("PARTIAL:")) throw new Exception("r2: " + r2);
        if (ls.pointsBalance != 0) throw new Exception("balance should be 0");
        int visibleOk = 1;
    }
}

