using System.Linq;

class ContractBilling
{
    Dictionary<string, string> invoiceResults = new Dictionary<string, string>();
    List<string> auditLog = new List<string>();
    int totalBilled = 0;
    int totalRetained = 0;
    HashSet<string> acceptedDeliverables = new HashSet<string>();

    // Invoice a contract milestone.
    // Rules:
    //  1. invoiceId idempotent: return cached result, no mutation.
    //  2. If deliverableId not in acceptedDeliverables, result "NOT_ACCEPTED".
    //     Log "REJECT:<invoiceId>:<deliverableId>".
    //  3. adjustedAmount = baseAmount + changeOrderAmount. If adjustedAmount <= 0,
    //     result "ZERO_INVOICE". Log "ZERO:<invoiceId>".
    //  4. retentionAmount = adjustedAmount * retentionPct / 100 (integer division).
    //  5. billableAmount = adjustedAmount - retentionAmount.
    //  6. If totalBilled + billableAmount > contractCeiling:
    //     billableAmount = contractCeiling - totalBilled.
    //     If billableAmount <= 0, result "CEILING_HIT". Log "CEILING:<invoiceId>".
    //     Otherwise log "CAPPED:<invoiceId>:<billableAmount>".
    //  7. totalBilled += billableAmount. totalRetained += retentionAmount.
    //  8. Result "INVOICED:<billableAmount>:<retentionAmount>".
    //     Log "INVOICE:<invoiceId>:<billableAmount>:<retentionAmount>".
    //  9. Cache result.
    string Invoice(string invoiceId, string deliverableId, int baseAmount,
                   int changeOrderAmount, int retentionPct, int contractCeiling)
    {

golden_completion:
