if (!acceptedDeliverables.Contains(deliverableId)) {
    auditLog.Add("REJECT:" + invoiceId + ":" + deliverableId);
    invoiceResults[invoiceId] = "NOT_ACCEPTED"; return "NOT_ACCEPTED";
}
int adj = baseAmount + changeOrderAmount;
if (adj <= 0) { auditLog.Add("ZERO:" + invoiceId); invoiceResults[invoiceId] = "ZERO_INVOICE"; return "ZERO_INVOICE"; }
int ret = adj * retentionPct / 100, bill = adj - ret;
if (totalBilled + bill > contractCeiling) {
    bill = contractCeiling - totalBilled;
    if (bill <= 0) { auditLog.Add("CEILING:" + invoiceId); invoiceResults[invoiceId] = "CEILING_HIT"; return "CEILING_HIT"; }
    auditLog.Add("CAPPED:" + invoiceId + ":" + bill);
}
totalBilled += bill; totalRetained += ret;
string result = "INVOICED:" + bill + ":" + ret;
auditLog.Add("INVOICE:" + invoiceId + ":" + bill + ":" + ret);
invoiceResults[invoiceId] = result;
return result;

