        public string Status { get; set; }  // "APPROVED","WAITLISTED","DENIED","DUPLICATE"
        public int QueuePosition { get; set; }
        public string Reason { get; set; }
    }

    public class VisaProcessor
    {
        public Dictionary<string, int> CategoryQuotas { get; set; }  // category -> remaining slots
        public Dictionary<string, List<string>> WaitLists { get; set; }
        public HashSet<string> ProcessedApplicants { get; set; }
        public HashSet<string> RequiredDocs { get; set; }
        public List<string> ProcessLog { get; set; }

        public VisaProcessor()
        {
            CategoryQuotas = new Dictionary<string, int>
            {
                { "EB1", 10 }, { "EB2", 20 }, { "EB3", 30 }, { "F1", 15 }
            };
            WaitLists = new Dictionary<string, List<string>>();
            foreach (var cat in CategoryQuotas.Keys) WaitLists[cat] = new List<string>();
            ProcessedApplicants = new HashSet<string>();
            RequiredDocs = new HashSet<string> { "PASSPORT", "I140", "MEDICAL", "PHOTO" };
            ProcessLog = new List<string>();
        }

        // Process a visa application.
        // Rules:
        //  1. Duplicate applicantId -> DUPLICATE, no mutation.
        //  2. Unknown category -> DENIED, reason "BAD_CATEGORY".
        //  3. Check documents: if any required doc is missing from submittedDocs,
        //     -> DENIED, reason "MISSING:<first missing doc alphabetically>".
        //  4. If CategoryQuotas[category] > 0: decrement quota, mark processed,
        //     status APPROVED. Log "APPROVED:<applicantId>:<category>".
        //  5. If quota == 0: add to WaitList. Position = WaitLists[cat].Count (1-indexed after add).
        //     status WAITLISTED. Log "WAITLISTED:<applicantId>:<category>:pos=<position>".
        //  6. dependents count does NOT affect quota (one slot per primary applicant).
        //     But log must include dependent count: append ":deps=<dependents>" to log entry.
        public VisaResult Process(string applicantId, string category,
                                   HashSet<string> submittedDocs, int dependents)
        {

