namespace QualityAssurance
{
    public class TestResult
    {
        public string TestName { get; set; }
        public double Value { get; set; }
        public double SpecMin { get; set; }
        public double SpecMax { get; set; }
    }

    public class BatchResult
    {
        public string Disposition { get; set; }  // "RELEASED", "REJECTED", "HOLD", "DUPLICATE"
        public int PassCount { get; set; }
        public int FailCount { get; set; }
        public List<string> FailedTests { get; set; }
        public string Reason { get; set; }
    }

    public class BatchProcessor
    {
        public int MaxOOSForHold { get; set; }   // max OOS results before auto-reject
        public HashSet<string> CriticalTests { get; set; }  // if critical test fails -> immediate reject
        public HashSet<string> ProcessedBatches { get; set; }
        public List<string> AuditTrail { get; set; }

        public BatchProcessor()
        {
            MaxOOSForHold = 2;
            CriticalTests = new HashSet<string> { "STERILITY", "ENDOTOXIN", "POTENCY" };
            ProcessedBatches = new HashSet<string>();
            AuditTrail = new List<string>();
        }

        // Evaluate batch for release.
        // Rules:
        //  1. Duplicate batchId -> DUPLICATE, no mutation.
        //  2. For each TestResult: pass if SpecMin <= Value <= SpecMax. Else fail (OOS).
        //  3. If any CriticalTest fails -> REJECTED immediately.
        //     Reason: "CRITICAL_FAIL:<testName>". No further tests evaluated after first critical fail.
        //     Wait -- actually all tests are evaluated, but disposition is decided after.
        //  4. Count pass/fail. Collect failed test names.
        //  5. If failCount == 0 -> RELEASED.
        //  6. If failCount <= MaxOOSForHold -> HOLD (investigation needed).
        //     Reason: "OOS_INVESTIGATION".
        //  7. If failCount > MaxOOSForHold -> REJECTED. Reason: "EXCESS_OOS".
        //  8. BUT: if any critical test is in the failed list, override to REJECTED
        //     regardless of fail count. Reason: "CRITICAL_FAIL:<first critical alphabetically>".
        //  9. Mark batch processed. Log "BATCH:<batchId>:<disposition>:pass=<pass>:fail=<fail>".
        public BatchResult Evaluate(string batchId, List<TestResult> results)
        {

