```c_sharp
            var result = new BatchResult
            {
                PassCount = 0,
                FailCount = 0,
                FailedTests = new List<string>()
            };

            if (ProcessedBatches.Contains(batchId))
            {
                result.Disposition = "DUPLICATE";
                result.Reason = "DUPLICATE";
                return result;
            }

            foreach (var t in results)
            {
                if (t.Value >= t.SpecMin && t.Value <= t.SpecMax)
                {
                    result.PassCount++;
                }
                else
                {
                    result.FailCount++;
                    result.FailedTests.Add(t.TestName);
                }
            }

            var failedCritical = result.FailedTests.Where(n => CriticalTests.Contains(n)).OrderBy(n => n).ToList();

            if (failedCritical.Count > 0)
            {
                result.Disposition = "REJECTED";
                result.Reason = "CRITICAL_FAIL:" + failedCritical[0];
            }
            else if (result.FailCount == 0)
            {
                result.Disposition = "RELEASED";
                result.Reason = "ALL_PASS";
            }
            else if (result.FailCount <= MaxOOSForHold)
            {
                result.Disposition = "HOLD";
                result.Reason = "OOS_INVESTIGATION";
            }
            else
            {
                result.Disposition = "REJECTED";
                result.Reason = "EXCESS_OOS";
            }

            ProcessedBatches.Add(batchId);
            AuditTrail.Add($"BATCH:{batchId}:{result.Disposition}:pass={result.PassCount}:fail={result.FailCount}");

            return result;
